from typing import List


def separate_paren_groups(paren_string: str) -> List[str]:
    """
    Input to this function is a string containing multiple groups of nested parentheses. Your goal is to
    separate those groups into separate strings and return the list of those.
    Separate groups are balanced (each open brace is properly closed) and not nested within each other
    Ignore any spaces in the input string.
    >>> separate_paren_groups('( ) (( )) (( )( ))')
    ['()', '(())', '(()())']
    """
    # Remove spaces from the input string
    paren_string = paren_string.replace(" ", "")

    def is_balanced(s: str) -> bool:
        """Check if the parentheses in s are balanced."""
        balance = 0
        for char in s:
            if char == '(':
                balance += 1
            elif char == ')':
                balance -= 1
                if balance < 0:
                    return False
        return balance == 0

    def find_group_start(s: str) -> int:
        """Find the starting index of the first unbalanced parenthesis group."""
        balance = 0
        for i, char in enumerate(s):
            if char == '(':
                balance += 1
            elif char == ')':
                balance -= 1
                if balance < 0:
                    return i
        return len(s)

    def find_group_end(s: str, start: int) -> int:
        """Find the ending index of the first unbalanced parenthesis group."""
        balance = 0
        for i in range(start, len(s)):
            if s[i] == '(':
                balance += 1
            elif s[i] == ')':
                balance -= 1
                if balance == 0:
                    return i
        return len(s)

    result = []
    start = 0
    while start < len(paren_string):
        end = find_group_end(paren_string, start)
        group = paren_string[start:end + 1]
        if is_balanced(group):
            result.append(group)
            start = end + 1
        else:
            start = end + 1
    return result

